type agreementRichCutHeadingSource struct {
	Cut, PrivateCut                        agreementRemovedCommentDiagnosticReading
	Native, PrivateNative                  agreementNativeHeadingSource
	Plain, Page, PrivatePlain, PrivatePage agreementMixedNamespaceReading
	IDs, PrivateIDs                        []string
	Private                                string
	OriginalSpan, ProjectedSpan            graph.Span
	Ordinal                                int
	Valid                                  bool
}

// Comment removal can expose another heading while preserving every physical
// line boundary. Its whole name allocation, including repeated bases, must
// agree with the page before one source interval can own a missing check name.
func agreementRichCutHeadingReading(body string, f *agreementFailure, page *agreementHTML) agreementRichCutHeadingSource {
	r := agreementRichCutHeadingSource{Ordinal: -1}
	if f == nil || page == nil || f.Property != "P4" || f.Identity != "literal-heading-id" || f.Direction != "page-only" || f.Multiplicity != 1 || f.Tuple != (agreementCitation{}) || !f.PagePresent || f.JudgeAccepted || f.ExcerptFound || f.Cut != "" || strings.Contains(body, "q") {
		return r
	}
	r.Cut = agreementCommentCutP0Reading(body)
	if !r.Cut.Valid {
		return r
	}
	r.Plain = agreementMixedNamespaceRead(r.Cut.Projected, agreementFootnoteGrammar)
	r.Page = agreementMixedNamespaceRead(r.Cut.Projected, agreementExclusiveCodeGrammar)
	if !r.Plain.Eligible || !r.Page.Eligible || !cmp.Equal(r.Plain, r.Page) {
		return r
	}
	r.IDs = agreementRichCutHeadingAllocate(r.Page.Bases)
	r.Native = agreementNativeHeadingReading(body)
	if !slices.Equal(r.IDs, page.Headings) || r.Native.Names[f.Fragment] || !slices.Equal(r.Native.Check.Targets, judge.LinkTargets(body)) {
		return r
	}
	for i, id := range r.IDs {
		if id == f.Fragment {
			if r.Ordinal >= 0 {
				return r
			}
			r.Ordinal = i
		}
	}
	if r.Ordinal < 0 || r.Ordinal >= len(r.Page.Headings) {
		return r
	}
	r.ProjectedSpan = r.Page.Headings[r.Ordinal]
	span := r.ProjectedSpan
	if span.Start < 0 || span.Stop <= span.Start || span.Stop > len(r.Cut.Positions) {
		return r
	}
	words := r.Cut.Projected[span.Start:span.Stop]
	if words != "<em>A</em>" && words != "`A" && words != "``A" {
		return r
	}
	start := r.Cut.Positions[span.Start]
	for i, at := range r.Cut.Positions[span.Start:span.Stop] {
		if at != start+i || at < 0 || at >= len(body) || body[at] != words[i] {
			return r
		}
	}
	r.OriginalSpan = graph.Span{Start: start, Stop: start + len(words)}
	private := []byte(body)
	copy(private[r.OriginalSpan.Start:r.OriginalSpan.Stop], strings.Repeat("q", len(words)))
	r.Private = string(private)
	r.PrivateCut = agreementCommentCutP0Reading(r.Private)
	r.PrivateNative = agreementNativeHeadingReading(r.Private)
	r.PrivatePlain = agreementMixedNamespaceRead(r.PrivateCut.Projected, agreementFootnoteGrammar)
	r.PrivatePage = agreementMixedNamespaceRead(r.PrivateCut.Projected, agreementExclusiveCodeGrammar)
	if !r.PrivateCut.Valid || !r.PrivatePlain.Eligible || !r.PrivatePage.Eligible || !cmp.Equal(r.PrivatePlain, r.PrivatePage) || !slices.Equal(r.Cut.Positions, r.PrivateCut.Positions) || !cmp.Equal(r.Cut.Check.Comments, r.PrivateCut.Check.Comments) || !slices.Equal(r.Native.Check.Targets, r.PrivateNative.Check.Targets) || !slices.Equal(r.PrivateNative.Check.Targets, judge.LinkTargets(r.Private)) {
		return r
	}
	expected := []byte(r.Cut.Projected)
	copy(expected[span.Start:span.Stop], strings.Repeat("q", len(words)))
	if string(expected) != r.PrivateCut.Projected || !cmp.Equal(r.Page.Headings, r.PrivatePage.Headings) || !cmp.Equal(r.Page.Code, r.PrivatePage.Code) || !cmp.Equal(r.Page.Fields, r.PrivatePage.Fields) || len(r.Page.Bases) != len(r.PrivatePage.Bases) || len(r.Page.Checks) != len(r.PrivatePage.Checks) {
		return r
	}
	for i := range r.Page.Bases {
		if i == r.Ordinal {
			if r.PrivatePage.Bases[i] != strings.Repeat("q", len(words)) || r.PrivatePage.Checks[i] != strings.Repeat("q", len(words)) {
				return r
			}
		} else if r.Page.Bases[i] != r.PrivatePage.Bases[i] || r.Page.Checks[i] != r.PrivatePage.Checks[i] {
			return r
		}
	}
	r.PrivateIDs = agreementRichCutHeadingAllocate(r.PrivatePage.Bases)
	r.Valid = true
	return r
}
func agreementRichCutHeadingAllocate(bases []string) []string {
	used := map[string]bool{}
	var ids []string
	for _, base := range bases {
		id := base
		for n := 2; used[id]; n++ {
			id = base + "-" + strconv.Itoa(n)
		}
		used[id] = true
		ids = append(ids, id)
	}
	return ids
}
func agreementRichCutHeadingEquation(ids []string, names map[string]bool, failures []agreementFailure) bool {
	expected := map[string]int{}
	for _, id := range ids {
		if !names[id] {
			f := agreementFailure{Property: "P4", Identity: "literal-heading-id", Fragment: id, Direction: "page-only", Multiplicity: 1, PagePresent: true}
			expected[agreementSignature(&f)]++
		}
	}
	actual := map[string]int{}
	for i := range failures {
		f := &failures[i]
		if f.Property == "P4" {
			actual[agreementSignature(f)]++
		}
	}
	return maps.Equal(expected, actual)
}
func agreementRichCutHeadingProjection(source *agreementRichCutHeadingSource, before, after []agreementFailure, page, privatePage *agreementHTML, diagnostics, privateDiagnostics []render.Diagnostic) bool {
	if source == nil || page == nil || privatePage == nil || !source.Valid || !slices.Equal(source.IDs, page.Headings) || !slices.Equal(source.PrivateIDs, privatePage.Headings) || !cmp.Equal(diagnostics, privateDiagnostics) || !agreementRichCutHeadingEquation(source.IDs, source.Native.Names, before) || !agreementRichCutHeadingEquation(source.PrivateIDs, source.PrivateNative.Names, after) {
		return false
	}
	a, b := *page, *privatePage
	a.Headings = nil
	b.Headings = nil
	if !cmp.Equal(a, b) {
		return false
	}
	original, private := map[string]int{}, map[string]int{}
	for i := range before {
		f := &before[i]
		if f.Property != "P4" {
			original[agreementSignature(f)]++
		}
	}
	for i := range after {
		f := &after[i]
		if f.Property != "P4" {
			private[agreementSignature(f)]++
		}
	}
	return maps.Equal(original, private)
}
func agreementRichCutHeadingDifference(c agreementCase, f *agreementFailure, html string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 {
		return "", "", ""
	}
	for i := range agreementRichCutHeadingDeclarations() {
		r := &agreementRichCutHeadingDeclarations()[i]
		if c.Body != r.Body || agreementSignature(f) != r.Selected {
			continue
		}
		if html != r.HTML || !cmp.Equal(*page, r.Page) || !cmp.Equal(diagnostics, r.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), agreementMixedCurrent(r.Before)) {
			return "", "", ""
		}
		source := agreementRichCutHeadingReading(c.Body, f, page)
		if !cmp.Equal(source, r.Source) || !agreementRichCutHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
			return "", "", ""
		}
		return "debt", "#1011 stage 8", "judge"
	}
	return "", "", ""
}
func agreementRichCutHeadingSelected(t *testing.T, r *agreementRichCutHeadingDeclaration) agreementFailure {
	t.Helper()
	var selected agreementFailure
	seen := 0
	for i := range r.Before {
		f := &r.Before[i]
		if agreementSignature(f) == r.Selected {
			selected = *f
			seen++
		}
	}
	if seen != 1 {
		t.Fatal("caught: unique rich cut heading declaration")
	}
	return selected
}
